                .attributeModifier<
      >(new ReaderPressFeedback(readerAppColor(this.value ? resolveReaderToggleSpec(this.specId).checkedColor :
                resolveReaderToggleSpec(this.specId).uncheckedColor, this.appThemeScheme), this.appThemeScheme, resolveReaderToggleSpec(this.specId).radius, resolveReaderToggleSpec(this.specId).pressedRadius, this.canAct(identity)))
                .responseRegion<
      >({ x: 0, y: resolveReaderToggleSpec(this.specId).responseY,
                width: resolveReaderToggleSpec(this.specId).width, height: resolveReaderToggleSpec(this.specId).responseHeight })
                .enabled<
      >(this.canAct(identity)).focusable<
      >(this.canAct(identity))
                .accessibilityRole<
      >(AccessibilityRoleType.SWITCH).accessibilityChecked<
      >(this.value)
                .accessibilityText<
      >(this.accessibilityLabel)
                .onClick<
