    >(visual.footerMetaLineHeight).halfLeading<
    >(true)
            .minFontScale<
    >(Math.min(1, this.footerFontScale())).maxFontScale<
    >(Math.max(1, this.footerFontScale()))
            .fontColor<
    >(mangaDirectoryColor('muted', this.scheme)).flexShrink<
    >(0);
    }
    @Builder
    private chapter() {
        .fontFamily<
    >(READER_FONT_NOTO_SANS_SC_UI_MEDIUM).fontWeight<
    >(visual.footerFontWeight)
            .fontSize<
    >(visual.footerTitleFontSize).lineHeight<
    >(visual.footerTitleLineHeight).halfLeading<
    >(true)
            .minFontScale<
    >(Math.min(1, this.footerFontScale())).maxFontScale<
    >(Math.max(1, this.footerFontScale()))
            .fontColor<
    >(mangaDirectoryColor('ink', this.scheme)).width<
    >('100%').maxLines<
    >(1).textOverflow<
    >({ overflow: TextOverflow.Ellipsis });
    }
    @Builder
    private page() {
        if (this.pagePosition.length > 0) {
            .fontFamily<
      >(READER_FONT_NOTO_SANS_SC_UI_REGULAR).fontWeight<
      >(visual.bodyFontWeight)
                .fontSize<
      >(visual.footerMetaFontSize).lineHeight<
      >(visual.footerMetaLineHeight).halfLeading<
      >(true).fontFeature<
      >("'tnum' 1")
                .minFontScale<
      >(Math.min(1, this.footerFontScale())).maxFontScale<
      >(Math.max(1, this.footerFontScale()))
                .fontColor<
      >(mangaDirectoryColor('muted', this.scheme)).wordBreak<
      >(WordBreak.BREAK_WORD).flexShrink<
      >(0);
