export function mangaDirectoryFooterStacked(contentWidth: number, fontScale: number, position: string): boolean {
    if (!Number.isFinite(contentWidth) || contentWidth <= 0)
        return false;
    const pageEm = Array.from(position).reduce((sum: number, character: string): number => sum + (character.charCodeAt(0) < 128 ? MANGA_DIRECTORY_VISUAL.numericDigitWidthEm : 1), 0);
    const reserved = (4 + pageEm) * MANGA_DIRECTORY_VISUAL.footerMetaFontSize * mangaDirectoryScale(fontScale) + MANGA_DIRECTORY_VISUAL.footerMinimumTitleEm * MANGA_DIRECTORY_VISUAL.footerTitleFontSize * mangaDirectoryScale(fontScale) + MANGA_DIRECTORY_VISUAL.footerGap * 2 + (MANGA_DIRECTORY_VISUAL.footerPaddingX + MANGA_DIRECTORY_VISUAL.borderWidth) * 2;
