        return true;
    return numberLengths.every((length: number): boolean => (length * MANGA_DIRECTORY_VISUAL.namedFontSize * MANGA_DIRECTORY_VISUAL.numericDigitWidthEm + (kind === 'parts' ? MANGA_DIRECTORY_VISUAL.namedFontSize * MANGA_DIRECTORY_VISUAL.partLabelWidthEm : 0)) * mangaDirectoryScale(fontScale) + (MANGA_DIRECTORY_VISUAL.gridPaddingX + MANGA_DIRECTORY_VISUAL.gridBorder) * 2 + Math.max(0, accessoryWidth) <= contentWidth);
